export async function runFeynmanGate(input: {
  concept: string
  artifact?: string
  sourceIds?: string[]
  targetAudience?: "child" | "operator" | "founder" | "engineer"
  mode: "learning" | "doctrine" | "gtm" | "code" | "strategy"
}) {
  const evidence = await retrieveEvidence(input.sourceIds, input.concept)

  const draft = await generateSimpleExplanation({
    concept: input.concept,
    artifact: input.artifact,
    evidence,
    targetAudience: input.targetAudience ?? "operator"
  })

  const gaps = await detectFeynmanGaps(draft, evidence)

  const revised = gaps.length
    ? await rewriteForClarity(draft, gaps, evidence)
    : draft

  const example = await generateConcreteExample(revised, input.mode)
  const analogy = await generateAnalogy(revised, input.mode)
  const recallQuestions = await generateRecallQuestions(revised)
  const applicationTask = await generateApplicationTask(revised, input.mode)

  const score = calculateFeynmanClarityScore({
    plainLanguage: scorePlainLanguage(revised),
    mechanism: scoreMechanism(revised),
    gapResolution: scoreGapResolution(gaps, revised),
    exampleQuality: scoreExample(example),
    analogyQuality: scoreAnalogy(analogy),
    jargonReduction: scoreJargonReduction(draft, revised)
  })

  const result = {
    status: score >= 80 ? "passed" : "blocked",
    score,
    simpleExplanation: revised,
    gaps,
    example,
    analogy,
    recallQuestions,
    applicationTask
  }

  await saveMemoryEvent({
    type: "feynman_gate",
    concept: input.concept,
    result,
    sourceIds: input.sourceIds
  })

  await scheduleReview({
    concept: input.concept,
    explanation: revised,
    recallQuestions
  })

  return result
}
