// packages/scoring/src/rig-os-score.ts

export type RigCriterionKey =
  | "identityForce"
  | "woundPrecision"
  | "euphoriaSpecificity"
  | "operationalStakes"
  | "doctrineDensity"
  | "contrastVoltage"
  | "cadenceControl"
  | "predictionError"
  | "tensionRelease"
  | "negativeSpace"
  | "graphIntegration"
  | "agenticExecution"
  | "memoryCompounding"
  | "calibrationLoop"
  | "approvalIntegrity"
  | "antiGenericForce"
  | "proprietaryLanguage"
  | "callbackDensity"
  | "extremeEdge"
  | "peakEndMemory";

export type RigScoreInput = Record<RigCriterionKey, number>;

export type RigScoreResult = {
  rawAverage: number;
  weightedScore: number;
  gatesPassed: boolean;
  blockedReasons: string[];
  interpretation: string;
};

const clamp = (n: number, min = 0, max = 10) => Math.max(min, Math.min(max, n));

const weights: Record<RigCriterionKey, number> = {
  identityForce: 0.07,
  woundPrecision: 0.05,
  euphoriaSpecificity: 0.04,
  operationalStakes: 0.05,
  doctrineDensity: 0.06,
  contrastVoltage: 0.05,
  cadenceControl: 0.04,
  predictionError: 0.06,
  tensionRelease: 0.04,
  negativeSpace: 0.03,
  graphIntegration: 0.07,
  agenticExecution: 0.08,
  memoryCompounding: 0.08,
  calibrationLoop: 0.07,
  approvalIntegrity: 0.06,
  antiGenericForce: 0.09,
  proprietaryLanguage: 0.05,
  callbackDensity: 0.04,
  extremeEdge: 0.05,
  peakEndMemory: 0.04,
};

export function scoreRigOS(input: RigScoreInput): RigScoreResult {
  const normalized = Object.fromEntries(
    Object.entries(input).map(([k, v]) => [k, clamp(v)])
  ) as RigScoreInput;

  const rawAverage =
    Object.values(normalized).reduce((sum, v) => sum + v, 0) /
    Object.values(normalized).length;

  const weightedScore =
    Object.entries(normalized).reduce((sum, [key, value]) => {
      return sum + value * (weights[key as RigCriterionKey] ?? 0);
    }, 0) * 10;

  const blockedReasons: string[] = [];

  if (normalized.antiGenericForce < 7.5) blockedReasons.push("AntiGenericForce below 75: too generic.");
  if (normalized.memoryCompounding < 7.0) blockedReasons.push("MemoryCompounding below 70: does not learn enough.");
  if (normalized.agenticExecution < 7.0) blockedReasons.push("AgenticExecution below 70: advises more than executes.");
  if (normalized.approvalIntegrity < 7.0) blockedReasons.push("ApprovalIntegrity below 70: unsafe or unauditable.");
  if (normalized.identityForce < 7.5) blockedReasons.push("IdentityForce below 75: does not feel like RIG.");
  if (normalized.peakEndMemory < 7.0) blockedReasons.push("PeakEndMemory below 70: ending does not land.");

  let interpretation = "Law-of-large-numbers product. Rebuild.";
  if (weightedScore >= 90) interpretation = "RIG-level. Ship.";
  else if (weightedScore >= 80) interpretation = "Strong but needs sharpening.";
  else if (weightedScore >= 70) interpretation = "Useful but too safe.";
  else if (weightedScore >= 60) interpretation = "Functional but generic.";

  return {
    rawAverage: Math.round(rawAverage * 10) / 10,
    weightedScore: Math.round(weightedScore * 10) / 10,
    gatesPassed: blockedReasons.length === 0 && weightedScore >= 80,
    blockedReasons,
    interpretation,
  };
}
